mapper.select:


    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
     and a.out_delivery_id = #{outDeliveryId}
     and a.material_id = #{materialId}
     and a.next_flag = #{nextFlag}
     and a.predict_count = #{predictCount}
     and a.receive_count = #{receiveCount}


${params.dataScope}
